/// Return the configured Ollama embedding model name.
///
/// Reads OLLAMA_EMBED_MODEL from the environment. Falls back to the default
/// when the variable is absent. Docker-compose uses ${OLLAMA_EMBED_MODEL:-}
/// for optional passthrough, which emits Ok("") when the host var is unset.
///
/// BUG: only handles Err (absent), not Ok("") (blank-but-set).
/// The docker-compose passthrough means Ok("") must be treated as absent.
pub fn embed_model() -> String {
    std::env::var("OLLAMA_EMBED_MODEL")
        .unwrap_or_else(|_| "qwen3-embedding:4b".to_string())
}
RSEOF
